import React, { useState, useRef } from 'react';
import { useMutation } from '@apollo/client';
import { CREATE_APPOINTMENT } from '../../graphql/mutations';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  Grid,
  MenuItem,
  Typography,
  Box,
  IconButton,
  CircularProgress
} from '@mui/material';
import { Close as CloseIcon } from '@mui/icons-material';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { TimePicker } from '@mui/x-date-pickers/TimePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import DocuSignModal from '../DocuSign/DocuSignModal';

const services = [
  'Tax Preparation',
  'Immigration Consultation',
  'Document Review',
  'Business Services',
  'Other'
];

const AppointmentModal = ({ open, onClose }) => {
  const [createAppointment, { loading: creating }] = useMutation(CREATE_APPOINTMENT, {
    onError: (error) => console.error('Error creating appointment:', error)
  });
  const [updateAppointment, { loading: updating }] = useMutation(UPDATE_APPOINTMENT, {
    onError: (error) => console.error('Error updating appointment:', error)
  });
  const isSubmitting = creating || updating;
  const [showDocuSign, setShowDocuSign] = useState(false);
  const formDataRef = useRef(null);
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    service: '',
    date: null,
    time: null,
    notes: ''
  });
  const [errors, setErrors] = useState({});

  const validate = () => {
    const newErrors = {};
    if (!formData.firstName) newErrors.firstName = 'First name is required';
    if (!formData.lastName) newErrors.lastName = 'Last name is required';
    if (!formData.email) {
      newErrors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = 'Email is invalid';
    }
    if (!formData.phone) newErrors.phone = 'Phone number is required';
    if (!formData.service) newErrors.service = 'Please select a service';
    if (!formData.date) newErrors.date = 'Please select a date';
    if (!formData.time) newErrors.time = 'Please select a time';

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleDateChange = (date) => {
    setFormData(prev => ({
      ...prev,
      date: date
    }));
  };

  const handleTimeChange = (time) => {
    setFormData(prev => ({
      ...prev,
      time: time
    }));
  };

  const handleSigningComplete = async (signedDocumentData) => {
    if (!formDataRef.current) return;

    try {
      // Update the appointment with DocuSign info
      const updateData = {
        id: formDataRef.current.id,
        documentSigned: true,
        envelopeId: signedDocumentData?.envelopeId,
        documentUrl: signedDocumentData?.documentUrl
      };

      // Call the update mutation
      const { data } = await updateAppointment({
        variables: {
          input: updateData
        }
      });

      console.log('Appointment updated with DocuSign info:', data.updateAppointment);

      // Show success message
      alert('Appointment booked successfully!');
      onClose();

    } catch (error) {
      console.error('Error updating appointment with DocuSign info:', error);
      setErrors(prev => ({
        ...prev,
        form: 'Appointment was created, but there was an error updating the signature status. Please contact support.'
      }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;

    try {
      // Loading state is handled by the mutation's loading state

      // Combine date and time
      const appointmentDateTime = new Date(formData.date);
      const [hours, minutes] = formData.time.split(':');
      appointmentDateTime.setHours(parseInt(hours, 10));
      appointmentDateTime.setMinutes(parseInt(minutes, 10));

      // Prepare the appointment data
      const appointmentData = {
        firstName: formData.firstName,
        lastName: formData.lastName,
        email: formData.email,
        phone: formData.phone,
        service: formData.service,
        appointment_date: appointmentDateTime.toISOString(),
        notes: formData.notes
      };

      // Save the form data for later use
      formDataRef.current = appointmentData;

      // Show DocuSign modal
      setShowDocuSign(true);
    } catch (error) {
      console.error('Error preparing appointment:', error);
      setErrors(prev => ({
        ...prev,
        form: 'Failed to prepare the appointment. Please try again.'
      }));
    }
  };

  return (
    <>
      <DocuSignModal
        open={showDocuSign}
        onClose={() => setShowDocuSign(false)}
        onSigningComplete={handleSigningComplete}
        formData={formData}
      />
      <Dialog 
      open={open} 
      onClose={onClose}
      maxWidth="md"
      fullWidth
      PaperProps={{
        sx: {
          borderRadius: 2,
          bgcolor: 'background.paper'
        }
      }}
    >
      <DialogTitle>
        <Box display="flex" justifyContent="space-between" alignItems="center">
          <Typography variant="h5" fontWeight={600}>
            Book an Appointment
          </Typography>
          <IconButton onClick={onClose} size="small">
            <CloseIcon />
          </IconButton>
        </Box>
      </DialogTitle>

      <form onSubmit={handleSubmit}>
        <DialogContent>
          <Grid container spacing={3}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="First Name"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
                error={!!errors.firstName}
                helperText={errors.firstName}
                margin="normal"
                variant="outlined"
                autoComplete="given-name"
                inputProps={{
                  'data-1p-ignore': true,
                  'data-lpignore': 'true',
                  'data-form-type': 'other'
                }}
                required
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Last Name"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                error={!!errors.lastName}
                helperText={errors.lastName}
                margin="normal"
                variant="outlined"
                autoComplete="family-name"
                inputProps={{
                  'data-1p-ignore': true,
                  'data-lpignore': 'true',
                  'data-form-type': 'other'
                }}
                required
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Email"
                name="email"
                type="email"
                value={formData.email}
                onChange={handleChange}
                error={!!errors.email}
                helperText={errors.email}
                margin="normal"
                variant="outlined"
                autoComplete="email"
                inputProps={{
                  'data-1p-ignore': true,
                  'data-lpignore': 'true',
                  'data-form-type': 'other'
                }}
                required
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Phone Number"
                name="phone"
                type="tel"
                value={formData.phone}
                onChange={handleChange}
                error={!!errors.phone}
                helperText={errors.phone}
                margin="normal"
                variant="outlined"
                autoComplete="tel"
                inputProps={{
                  'data-1p-ignore': true,
                  'data-lpignore': 'true',
                  'data-form-type': 'other',
                  inputMode: 'tel'
                }}
                required
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                select
                label="Service Needed"
                name="service"
                value={formData.service}
                onChange={handleChange}
                error={!!errors.service}
                helperText={errors.service}
                margin="normal"
                variant="outlined"
                required
              >
                {services.map((service) => (
                  <MenuItem key={service} value={service}>
                    {service}
                  </MenuItem>
                ))}
              </TextField>
            </Grid>
            <Grid item xs={12} sm={6}>
              <LocalizationProvider dateAdapter={AdapterDateFns}>
                <DatePicker
                  label="Appointment Date"
                  value={formData.date}
                  onChange={handleDateChange}
                  renderInput={(params) => (
                    <TextField
                      {...params}
                      fullWidth
                      margin="normal"
                      error={!!errors.date}
                      helperText={errors.date}
                      required
                    />
                  )}
                  minDate={new Date()}
                />
              </LocalizationProvider>
            </Grid>
            <Grid item xs={12} sm={6}>
              <LocalizationProvider dateAdapter={AdapterDateFns}>
                <TimePicker
                  label="Preferred Time"
                  value={formData.time}
                  onChange={handleTimeChange}
                  shouldDisableTime={(timeValue, clockType) => {
                    if (clockType === 'minutes') {
                      // Only allow times on the hour or half hour
                      return timeValue % 30 !== 0;
                    }
                    return false;
                  }}
                  renderInput={(params) => (
                    <TextField
                      {...params}
                      fullWidth
                      margin="normal"
                      error={!!errors.time}
                      helperText={errors.time || 'Available between 9:00 AM - 5:00 PM'}
                      required
                    />
                  )}
                  ampm={true}
                  minutesStep={30}
                />
              </LocalizationProvider>
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Additional Notes (Optional)"
                name="notes"
                value={formData.notes}
                onChange={handleChange}
                margin="normal"
                variant="outlined"
                multiline
                rows={4}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions sx={{ p: 3, pt: 0 }}>
          <Button 
            onClick={onClose} 
            color="inherit"
            sx={{ mr: 2 }}
          >
            Cancel
          </Button>
          <Button
            type="submit"
            variant="contained"
            color="primary"
            disabled={isSubmitting}
            startIcon={isSubmitting ? <CircularProgress size={20} /> : null}
          >
            {isSubmitting ? 'Submitting...' : 'Book Appointment'}
          </Button>
        </DialogActions>
      </form>
    </Dialog>
    </>
  );
};

export default AppointmentModal;
